// Called during initialization
void InitializeVideoMode(void) {
    // Mode 3 Extended is set up by the kernel
    // Clear VRAM
    ClearVram();
    
    // Copy sprite tiles to RAM tile area
    // This would be done by the Uzebox kernel
}

// =============================================================================
// MAIN ENTRY POINT
// =============================================================================

int main(void) {
    // Initialize video
    InitializeVideoMode();
    
    // Initialize game
    game_init(1);  // Start with 1 player
    
    // Main loop
    while(1) {
        GameLoop();  // From game.c
    }
    
    return 0;
}

